return ['domain'=>'gpx-route-map','plural-forms'=>'nplurals=2; plural=(n != 1);','language'=>'es_ES','project-id-version'=>'GPX Route Map 2.1.0','pot-creation-date'=>'2026-10-16T11:16:42+00:00','po-revision-date'=>'2026-10-16T11:22:05+00:00','messages'=>['GPX Route Map'=>'GPX Route Map','https://github.com/SirLouen/gpx-route-map'=>'https://github.com/SirLouen/gpx-route-map','Attach a GPX track to any post or page and render it as an interactive OpenStreetMap map with waypoints, distance and an elevation profile.'=>'Adjunta una pista GPX a cualquier entrada o página y muéstrala como un mapa interactivo de OpenStreetMap con waypoints, distancia y un perfil de desnivel.','SirLouen <sir.louen@gmail.com>'=>'SirLouen <sir.louen@gmail.com>','https://github.com/SirLouen'=>'https://github.com/SirLouen','GPX Route Map: no GPX file selected.'=>'GPX Route Map: no se ha seleccionado ningún archivo GPX.','GPX Route Map: plugin assets are not built. Run "pnpm install && pnpm run build" in the plugin directory.'=>'GPX Route Map: los recursos del plugin no están compilados. Ejecuta «pnpm install && pnpm run build» en el directorio del plugin.','Interactive route map'=>'Mapa interactivo de la ruta','Loading map…'=>'Cargando el mapa…','Scroll or tap to load the interactive map'=>'Desplázate o toca para cargar el mapa interactivo','Could not load GPX file.'=>'No se ha podido cargar el archivo GPX.','Could not load GPX file: its host does not allow cross-origin (CORS) requests. Upload the file to this site instead.'=>'No se ha podido cargar el archivo GPX: su servidor no permite peticiones de origen cruzado (CORS). Sube el archivo a este sitio en su lugar.','Invalid GPX file.'=>'Archivo GPX no válido.','No track or route points found in GPX file.'=>'No se han encontrado puntos de pista ni de ruta en el archivo GPX.','Distance'=>'Distancia','Elevation gain'=>'Desnivel positivo','Elevation loss'=>'Desnivel negativo','Max elevation'=>'Altitud máxima','Waypoints'=>'Waypoints','Elevation profile'=>'Perfil de desnivel','Elevation profile along the route'=>'Perfil de desnivel a lo largo de la ruta','Paste a direct link to a .gpx file. The file must be hosted on this site, or on a host that allows cross-origin (CORS) requests — most external sites do not.'=>'Pega un enlace directo a un archivo .gpx. El archivo debe estar alojado en este sitio o en un servidor que permita peticiones de origen cruzado (CORS); la mayoría de los sitios externos no lo permiten.','Currently using the selected media file "%s". Entering a URL here replaces it (applied on Enter or when leaving the field).'=>'Actualmente se usa el archivo de medios seleccionado «%s». Si introduces una URL aquí, la sustituirás (se aplica al pulsar Intro o al salir del campo).','Source'=>'Origen','Replace GPX file'=>'Reemplazar el archivo GPX','Select GPX file'=>'Seleccionar un archivo GPX','or GPX file URL'=>'o URL del archivo GPX','Display'=>'Visualización','Max zoom'=>'Zoom máximo','Map tiles'=>'Teselas del mapa','Replace GPX'=>'Reemplazar GPX','Select a GPX track to render it as an interactive map with an elevation profile.'=>'Selecciona una pista GPX para mostrarla como un mapa interactivo con un perfil de desnivel.','The interactive map renders on the front end.'=>'El mapa interactivo se muestra en la parte pública del sitio.','Stats'=>'Estadísticas','Open GPX file'=>'Abrir el archivo GPX','block titleGPX Route Map'=>'GPX Route Map','block descriptionRender a GPX track as an interactive OpenStreetMap map with waypoints, distance and an elevation profile.'=>'Muestra una pista GPX como un mapa interactivo de OpenStreetMap con waypoints, distancia y un perfil de desnivel.','block keywordgpx'=>'gpx','block keywordmap'=>'mapa','block keywordroute'=>'ruta','block keywordelevation'=>'desnivel','block keywordopenstreetmap'=>'openstreetmap','block keywordtrail'=>'sendero','block keywordhiking'=>'senderismo','block keywordcycling'=>'ciclismo','Metric (km / m)'=>'Métrico (km / m)','Imperial (mi / ft)'=>'Imperial (mi / ft)','Units used for distance and elevation on GPX maps. Individual maps can override this.'=>'Unidades de distancia y desnivel en los mapas GPX. Cada mapa puede usar unas distintas.','unitmi'=>'mi','unitft'=>'ft','unitkm'=>'km','unitm'=>'m','Units'=>'Unidades','Distance and elevation units for this map.'=>'Unidades de distancia y desnivel de este mapa.','Site default'=>'Ajuste del sitio','Stats bar'=>'Barra de estadísticas','Defaults for every GPX map on this site. Individual maps can override them.'=>'Valores predeterminados para todos los mapas GPX de este sitio. Cada mapa puede cambiarlos.','Shown'=>'Mostrar','Hidden'=>'Ocultar','Download button'=>'Botón de descarga','Download GPX file'=>'Descargar el archivo GPX','Adds a button on the map for visitors to download the GPX file.'=>'Añade un botón en el mapa para que los visitantes descarguen el archivo GPX.','Stats shown'=>'Estadísticas mostradas','Stats bar items'=>'Elementos de la barra de estadísticas','Use site default'=>'Usar el ajuste del sitio','Which figures the stats bar lists. To remove the bar altogether, set Stats bar to Hidden.'=>'Esas son las cifras que aparecen en la barra de estadísticas. Para eliminar la barra por completo, configura la opción «Barra de estadísticas» en «Oculta».','Tile provider'=>'Proveedor de teselas','Thunderforest API key'=>'Clave de API de Thunderforest','Where the map images come from. Visitors load these directly from the provider, so the provider receives their IP address and the area of the map being viewed.'=>'De dónde salen las imágenes del mapa. Los visitantes las cargan directamente del proveedor, así que este recibe su dirección IP y la zona del mapa que se está viendo.','That does not look like a Thunderforest API key. Keys are 32 letters and numbers, with nothing else in between.'=>'Esto no parece una clave de API de Thunderforest. Las claves son 32 letras y números, sin nada más entre medias.','OpenStreetMap works with no setup. Thunderforest offers outdoor and cycling styles, and needs an account.'=>'OpenStreetMap funciona sin configurar nada. Thunderforest ofrece estilos para montaña y ciclismo, y necesita una cuenta.','Get a free key at %s. The free plan covers 150,000 map tiles a month, which is roughly 8,000 map views.'=>'Consigue una clave gratuita en %s. El plan gratuito cubre 150.000 teselas al mes, que son unas 8.000 visitas con mapa.','The key is visible in your pages, because visitors\' browsers load the tiles. Thunderforest cannot restrict a key to your domain, so keep an eye on your usage.'=>'La clave queda visible en tus páginas, porque son los navegadores de los visitantes los que cargan las teselas. Thunderforest no permite restringir una clave a tu dominio, así que vigila tu consumo.','Outdoors (hiking)'=>'Outdoors (senderismo)','OpenCycleMap (cycling)'=>'OpenCycleMap (ciclismo)','Landscape (terrain)'=>'Landscape (relieve)','Atlas (general)'=>'Atlas (general)','Map failed to load. Click to retry.'=>'No se ha podido cargar el mapa. Haz clic para reintentar.','Follow the stats chosen under Settings → GPX Route Map.'=>'Sigue las estadísticas que hayas elegido en Ajustes → GPX Route Map.','Map height'=>'Altura del mapa','px'=>'px','Use site default height'=>'Usar la altura del sitio','Follow the height set under Settings → GPX Route Map (%d px).'=>'Usa la altura definida en Ajustes → GPX Route Map (%d px).','All screens'=>'Todas las pantallas','Tablet'=>'Tableta','Same as above'=>'Igual que lo de arriba','Mobile'=>'Móvil','Same as tablet'=>'Igual que en tableta','Height of every GPX map that does not set its own, from %1$d to %2$d pixels. Leave Tablet or Mobile empty to reuse the size above it. Individual maps can override all of this.'=>'Altura de los mapas GPX que no definen la suya, de %1$d a %2$d píxeles. Deja Tableta o Móvil en blanco para reutilizar el tamaño de arriba. Cada mapa puede anular todo esto.','All screens (px)'=>'Todas las pantallas (px)','Tablet (px)'=>'Tableta (px)','Mobile (px)'=>'Móvil (px)','Applies at 782px and below. Reset to follow the site setting, or the height above when the site has none.'=>'Se aplica a 782px o menos. Restablécelo para seguir el ajuste del sitio, o la altura de arriba si el sitio no define ninguna.','Applies at 480px and below. Reset to follow the site setting, or the tablet height when the site has none.'=>'Se aplica a 480px o menos. Restablécelo para seguir el ajuste del sitio, o la altura de tableta si el sitio no define ninguna.','popup on the pin marking where the route beginsStart'=>'Inicio','popup on the pin marking where the route finishesEnd'=>'Fin','screen reader name of the map areaMap'=>'Mapa','map buttonZoom in'=>'Acercar','map buttonZoom out'=>'Alejar','map compass buttonDrag to rotate map, click to reset north'=>'Arrastra para girar el mapa, haz clic para orientarlo al norte','map buttonEnter fullscreen'=>'Ver a pantalla completa','map buttonExit fullscreen'=>'Salir de pantalla completa','map buttonFind my location'=>'Buscar mi ubicación','map button, when the browser cannot tell where the visitor isLocation not available'=>'Ubicación no disponible','map button that shows or hides the map creditsToggle attribution'=>'Mostrar u ocultar los créditos del mapa','button in a map popupClose popup'=>'Cerrar ventana emergente','unit on the map scale barm'=>'m','Min elevation'=>'Altitud mínima','OpenTopoMap shows contour lines and hill shading, also with no setup. It is run by volunteers, with no guarantee it stays available, and has less detail close in.'=>'OpenTopoMap muestra curvas de nivel y sombreado del relieve, también sin configurar nada. Lo mantienen voluntarios, sin garantía de que siga disponible, y tiene menos detalle de cerca.','No Thunderforest API key is saved, so maps that follow the site use OpenStreetMap until you add one.'=>'No hay ninguna clave de API de Thunderforest guardada, así que los mapas que siguen el ajuste del sitio usan OpenStreetMap hasta que añadas una.','The key also makes the Thunderforest styles available for single maps. Maps set to one use the site\'s provider while no key is saved.'=>'La clave también permite usar los estilos de Thunderforest en mapas concretos. Los mapas configurados con uno de ellos usan el proveedor del sitio mientras no haya ninguna clave guardada.','How close a map opens when it frames a short route, from %1$d to %2$d, though never closer than its tile provider has tiles. Visitors can zoom in as far as those tiles go. Individual maps can override it.'=>'Cuánto se acerca un mapa al abrirse si encuadra una ruta corta, de %1$d a %2$d, aunque nunca más de lo que permiten las teselas de su proveedor. Los visitantes pueden acercarse hasta donde lleguen esas teselas. Cada mapa puede cambiarlo.','Thunderforest: %s'=>'Thunderforest: %s','How close this map opens when it frames a short route, though never closer than its tile provider has tiles. Reset to follow the site setting (%d).'=>'Cuánto se acerca este mapa al abrirse si encuadra una ruta corta, aunque nunca más de lo que permiten las teselas de su proveedor. Restablécelo para seguir el ajuste del sitio (%d).','Thunderforest styles appear here once an API key is saved under Settings → GPX Route Map.'=>'Los estilos de Thunderforest aparecerán aquí cuando se guarde una clave de API en Ajustes → GPX Route Map.','Site default — %s'=>'Ajuste del sitio — %s','%s — needs an API key'=>'%s — necesita una clave de API','Individual maps can choose their own provider.'=>'Cada mapa puede elegir su propio proveedor.','General'=>'General','Enable Waypoint posts (experimental)'=>'Activar las entradas de waypoint (experimental)','Adds a Waypoints menu. Each waypoint post can have its own description, a photo or an icon, and maps show them on the waypoints of their GPX files that link to it.'=>'Añade un menú «Waypoints». Cada entrada de waypoint puede tener su propia descripción, una foto o un icono, y los mapas los muestran en los waypoints de sus archivos GPX que enlacen con ella.','A map\'s block links its GPX file\'s waypoints in its Waypoints panel, or a GPX file can name the post itself.'=>'El bloque de un mapa enlaza los waypoints de su archivo GPX en su panel «Waypoints», o el propio archivo GPX puede indicar la entrada.','This site cannot read the links a GPX file names itself, as its PHP lacks the XMLReader extension. Links made in a map\'s block or shortcode still work.'=>'Este sitio no puede leer los enlaces que indica el propio archivo GPX, porque a su PHP le falta la extensión XMLReader. Los enlaces hechos en el bloque o el shortcode de un mapa siguen funcionando.','Marker'=>'Marcador','ID'=>'ID','Photo'=>'Foto','Icon: %s'=>'Icono: %s','Usual marker'=>'Marcador habitual','Waypoint'=>'Waypoint','Description'=>'Descripción','What visitors read when they open this waypoint on a map, in place of the description in the GPX file. Links, bold and italic text, and lists are kept.'=>'Lo que leen los visitantes al abrir este waypoint en un mapa, en lugar de la descripción del archivo GPX. Se conservan los enlaces, la negrita, la cursiva y las listas.','The marker the map gives this waypoint, from its type in the GPX file.'=>'El marcador que el mapa da a este waypoint según su tipo en el archivo GPX.','A thumbnail of the photo set in the Photo box. Without one, the usual marker.'=>'Una miniatura de la foto elegida en la caja «Foto». Si no hay ninguna, el marcador habitual.','Icon'=>'Icono','An icon of your choice, in your own colors.'=>'Un icono a tu elección, con tus propios colores.','Icon color'=>'Color del icono','Background color'=>'Color de fondo','Search icons'=>'Buscar iconos','Preview:'=>'Vista previa:','Waypoint ID: %d'=>'ID del waypoint: %d','A map shows this waypoint when its block links one of the GPX file\'s waypoints to it. Or a GPX file in the Media Library can link to it itself: put this at the end of the waypoint\'s <wpt> element, or only its middle line inside the waypoint\'s <extensions> if it has one.'=>'Un mapa muestra este waypoint cuando su bloque enlaza con él uno de los waypoints del archivo GPX. O un archivo GPX de la biblioteca de medios puede enlazarlo por sí mismo: pon esto al final del elemento <wpt> del waypoint, o solo su línea central dentro del elemento <extensions> del waypoint si ya tiene uno.','GPX extension that links a waypoint to this one'=>'Extensión GPX que enlaza un waypoint con este','All Waypoints'=>'Todos los waypoints','Add Waypoint'=>'Añadir waypoint','Edit Waypoint'=>'Editar waypoint','New Waypoint'=>'Nuevo waypoint','Search Waypoints'=>'Buscar waypoints','No waypoints found.'=>'No se han encontrado waypoints.','No waypoints found in Trash.'=>'No se han encontrado waypoints en la papelera.','Waypoint published.'=>'Waypoint publicado.','Waypoint updated.'=>'Waypoint actualizado.','Set photo'=>'Establecer la foto','Remove photo'=>'Quitar la foto','Use as photo'=>'Usar como foto','Waypoints that GPX maps link to, each with its own description, photo or icon.'=>'Waypoints a los que enlazan los mapas GPX, cada uno con su propia descripción, foto o icono.','This GPX file links waypoints to Waypoint posts itself, but this site cannot read those links, as its PHP lacks the XMLReader extension. Link them here instead.'=>'Este archivo GPX enlaza por sí mismo waypoints con entradas de waypoint, pero este sitio no puede leer esos enlaces, porque a su PHP le falta la extensión XMLReader. Enlázalos aquí en su lugar.','This GPX file links waypoints to Waypoint posts itself, but maps only read those links from files in the Media Library. Link them here instead, or choose the file from the Media Library.'=>'Este archivo GPX enlaza por sí mismo waypoints con entradas de waypoint, pero los mapas solo leen esos enlaces en archivos de la biblioteca de medios. Enlázalos aquí en su lugar, o elige el archivo desde la biblioteca de medios.','#%d (no title)'=>'#%d (sin título)','%s (not published)'=>'%s (sin publicar)','#%d (not found)'=>'#%d (no encontrado)','None'=>'Ninguno','As in the GPX file: %s'=>'Como en el archivo GPX: %s','%1$d. %2$s'=>'%1$d. %2$s','Link a waypoint of the GPX file to a Waypoint post to show its description, photo or icon. Only published waypoints show on the map.'=>'Enlaza un waypoint del archivo GPX con una entrada de waypoint para mostrar su descripción, foto o icono. En el mapa solo se muestran los waypoints publicados.','This GPX file has no waypoints.'=>'Este archivo GPX no tiene waypoints.','Add a waypoint'=>'Añadir un waypoint']];